import type { Viewport } from "next";
// Self-hosted fonts for all three type pairings (generated by
// scripts/build-fonts.mjs). Browsers download only the faces a page uses;
// the active pairing's main files are preloaded in app/[site]/layout.tsx.
import "./fonts.css";
import "./globals.css";
import "./magazine.css";
import "./admin.css";

export const viewport: Viewport = {
  width: "device-width",
  initialScale: 1,
  themeColor: [
    { media: "(prefers-color-scheme: light)", color: "#ffffff" },
    { media: "(prefers-color-scheme: dark)", color: "#0e1013" },
  ],
};

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    // The age-gate boot script sets data-age-ok before hydration.
    <html lang="en" suppressHydrationWarning>
      <body>{children}</body>
    </html>
  );
}
